"""API-key authentication for the LocalAiStudio backend.

LocalAiStudio is a 100 % local desktop application: the FastAPI backend listens on 127.0.0.1 and
the React frontend (Vite dev server) proxies ``/api/*`` calls to it.

No request is ever authorised *because* it comes from localhost.  Session initialisation uses a
**one-time bootstrap token** generated by the Windows launcher (``start-localaistudio.bat``) and
passed to both the backend and the Vite proxy via the ``LAS_BOOT_TOKEN`` environment variable.
The frontend calls ``POST /api/auth/init``; the Vite proxy injects the token as an
``X-Boot-Token`` header on that request only; the backend validates it, issues an httpOnly
``SameSite=Strict`` session cookie, and invalidates the token (one-time use).  No secret is
embedded in the frontend bundle.

Threat model addressed
-----------------------
* Malicious websites → CORS restricted to loopback origins (server.py) + token required.
* Generated-site JS → iframe ``sandbox="allow-scripts allow-forms"`` (no ``allow-same-origin``)
  + ``Content-Security-Policy: connect-src 'none'; form-action 'none'`` on preview responses
  (routers/projects.py) blocks fetch/XHR and form submissions even though the preview shares
  the backend origin.
* Public tunnels → tunnel-preview.bat no longer creates unauthenticated Cloudflare tunnels.
* Direct backend access → 401 without a valid session cookie or API key.
* Localhost auto-bootstrap → **removed** (V1-B.2): no request is authorised solely because it
  comes from loopback.
"""
import json
import os
import secrets
from pathlib import Path
from typing import Optional

from starlette.types import ASGIApp, Receive, Scope, Send

# -- persistent API key --------------------------------------------------------

_KEY_FILE = Path(__file__).resolve().parent.parent / ".api_key"
# Overridable so two editions on the same host (e.g. installed + V2-E on 127.0.0.1) keep separate sessions.
COOKIE_NAME = os.environ.get("LAS_SESSION_COOKIE", "").strip() or "las_session"


def _load_or_create_key() -> str:
    """Return the persistent API key, creating a random one on first run."""
    if _KEY_FILE.exists():
        key = _KEY_FILE.read_text().strip()
        if key:
            return key
    key = secrets.token_hex(32)
    try:
        _KEY_FILE.write_text(key)
        try:
            _KEY_FILE.chmod(0o600)
        except (OSError, NotImplementedError):
            pass
    except OSError:
        pass
    return key


API_KEY = _load_or_create_key()

# -- one-time bootstrap token --------------------------------------------------

_BOOT_FILE = Path(__file__).resolve().parent.parent / ".boot_token"


def _init_boot_token() -> str:
    """Return the one-time bootstrap token.

    The token comes from the ``LAS_BOOT_TOKEN`` env var (set by ``start-localaistudio.bat``).
    If the env var is not set (manual dev without the launcher), a random token is generated
    and written to ``backend/.boot_token`` so the Vite dev server can read it and inject it
    into the ``/api/auth/init`` request via the proxy ``configure`` hook.
    """
    token = os.environ.get("LAS_BOOT_TOKEN")
    if token:
        return token
    token = secrets.token_hex(32)
    try:
        _BOOT_FILE.write_text(token)
        try:
            _BOOT_FILE.chmod(0o600)
        except (OSError, NotImplementedError):
            pass
    except OSError:
        pass
    return token


def tokens_equal(left: str, right: str) -> bool:
    """Compare tokens without timing leaks and accept malformed non-ASCII inputs safely."""
    return secrets.compare_digest(left.encode("utf-8"), right.encode("utf-8"))


class _BootToken:
    """Manages the one-time bootstrap token: ``consume()`` invalidates it after first use."""

    def __init__(self) -> None:
        self._token = _init_boot_token()
        self._consumed = False

    def consume(self, token: str) -> bool:
        """Return True if *token* matches and hasn't been consumed yet; invalidate it."""
        if self._consumed or not token or not tokens_equal(token, self._token):
            return False
        self._consumed = True
        try:
            _BOOT_FILE.unlink(missing_ok=True)
        except (OSError, NotImplementedError):
            pass
        return True

    @property
    def token(self) -> str:
        return self._token

    @property
    def is_consumed(self) -> bool:
        return self._consumed

    def _reset(self) -> None:
        """Test-only: reset to allow re-use across test runs."""
        self._consumed = False


boot = _BootToken()

# -- exempt paths --------------------------------------------------------------

# Paths that never require a token: preview HTML (served to sandboxed generated sites),
# media file serving (images/videos referenced by <img>/<video> tags), health check,
# and the one-time session-initialisation endpoint (which validates the boot token itself).
_EXEMPT_PREFIXES = ("/api/preview/",)
_HEALTH_PATHS = frozenset({"/api", "/api/"})


def _is_exempt(path: str) -> bool:
    if path in _HEALTH_PATHS or path == "/api/auth/init":
        return True
    if any(path.startswith(p) for p in _EXEMPT_PREFIXES):
        return True
    # /api/media/{id}/file  — public asset serving for generated-site previews
    if path.startswith("/api/media/") and path.endswith("/file"):
        return True
    return False


def _extract_token(scope: Scope) -> Optional[str]:
    """Return the bearer token from the ``X-API-Key`` header or the ``las_session`` cookie."""
    raw_cookie = None
    for name, value in scope.get("headers", []):
        if name == b"x-api-key" and value.strip():
            return value.decode("latin-1")
        if name == b"cookie":
            raw_cookie = value.decode("latin-1")
    if raw_cookie:
        for part in raw_cookie.split(";"):
            k, _, v = part.strip().partition("=")
            if k == COOKIE_NAME and v:
                return v
    return None


# -- ASGI middleware -----------------------------------------------------------


class AuthMiddleware:
    """Pure ASGI auth middleware (no BaseHTTPMiddleware — safe with StreamingResponse).

    Flow:
      1. OPTIONS, non-/api, public asset reads, and POST /api/auth/init → pass through.
      2. Valid X-API-Key header or configured session cookie → pass through.
      3. Anything else → 401 JSON.

    No request is ever authorised because it comes from localhost.
    Session initialisation is handled by ``POST /api/auth/init`` (server.py) which
    validates a one-time bootstrap token from the Windows launcher.
    """

    def __init__(self, app: ASGIApp) -> None:
        self.app = app

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "http":
            return await self.app(scope, receive, send)

        path = scope["path"]
        method = scope["method"]

        # Public previews/media are read-only; bootstrap is explicitly POST-only.
        is_public_read = method in {"GET", "HEAD"} and _is_exempt(path) and path != "/api/auth/init"
        is_bootstrap = method == "POST" and path == "/api/auth/init"
        if method == "OPTIONS" or not path.startswith("/api") or is_public_read or is_bootstrap:
            return await self.app(scope, receive, send)

        token = _extract_token(scope)
        if token is not None and tokens_equal(token, API_KEY):
            return await self.app(scope, receive, send)

        # No auto-bootstrap: reject ALL unauthenticated requests, including localhost.
        body = json.dumps({"detail": "Authentification requise"}).encode("latin-1")
        await send(
            {
                "type": "http.response.start",
                "status": 401,
                "headers": [
                    (b"content-type", b"application/json"),
                    (b"content-length", str(len(body)).encode("latin-1")),
                ],
            }
        )
        await send({"type": "http.response.body", "body": body})
